Ltac vm_popc :=
  match goal with |- context [bv_unsigned (popcw ?w)] =>
    let v := eval vm_compute in (bv_unsigned (popcw w)) in
    replace (bv_unsigned (popcw w)) with v by (vm_compute; reflexivity) end.

