  Lemma loopP : forall l2 l1 p k v R,
    ents = l1 ++ (p, (k, v)) :: l2 -> bc = 2 ->
    getr R 10%bv = Z_to_bv 64 p -> getr R 11%bv = Z_to_bv 64 key -> getr R 12%bv = Z_to_bv 64 (bc - 1) ->
    getr R 13%bv = Z_to_bv 64 (key mod bc) -> getr R 14%bv = sxw key ->
